local spells
function ns.GetEnchantSpell(enchantId)
    if not spells then
        local key = ns.IS_RETAIL and "retail" or ((ns.BlizzardStats and ns.BlizzardStats.IsAvailable()) and "forever" or "mop")
        spells = {}
        for id, spell in DATA[key]:gmatch("(%d+):(%d+)") do
            spells[tonumber(id)] = tonumber(spell)
        end
        DATA = nil
    end
    return spells[enchantId]
end
